function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function firstPresent(...values) {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim() === '') continue;
    return value;
  }
  return '';
}

function nameOf(value) {
  if (isObject(value)) return firstPresent(value.name, value.displayName, value.nodeName, value.id, value.workflowName, '');
  return value;
}

function redact(value) {
  let s = typeof value === 'string' ? value : JSON.stringify(value ?? '');
  s = s.replace(/Bearer\s+[A-Za-z0-9._\-]+/gi, 'Bearer REDACTED');
  s = s.replace(/("?(?:access[_-]?token|api[_-]?key|authorization|password|secret|credential|client[_-]?secret|refresh[_-]?token)"?\s*[:=]\s*"?)[^"\s,}&]+/gi, '$1REDACTED');
  s = s.replace(/([?&](?:access_token|api_key|key|token|secret)=)[^&\s]+/gi, '$1REDACTED');
  s = s.replace(/\bsk-[A-Za-z0-9_\-]{20,}\b/g, 'REDACTED');
  s = s.replace(/\bsk-proj-[A-Za-z0-9_\-]+\b/g, 'REDACTED');
  s = s.replace(/\b[0-9]{8,12}:[A-Za-z0-9_\-]{25,}\b/g, 'REDACTED');
  s = s.replace(/https?:\/\/[^\s"'<>]+/gi, (url) => {
    try {
      const u = new URL(url);
      if (/webhook|access_token|api_key|token|secret|key=/i.test(url)) return u.origin + '/REDACTED_URL';
      return u.origin + '/...';
    } catch (_) {
      return 'REDACTED_URL';
    }
  });
  s = s.replace(/\b[A-Za-z0-9_\-]{80,}\b/g, 'REDACTED_LONG_VALUE');
  return s;
}

function compactText(value, max = 180) {
  let s = redact(value);
  s = s.replace(/\r/g, '\n');
  s = s.split(/\n\s*at\s+|\n\s*stack\s*:|\n\s*Stack trace\s*:/i)[0];
  s = s.replace(/\s+/g, ' ').trim();
  if (!s) return '';
  return s.length > max ? s.slice(0, max - 3) + '...' : s;
}

function pickErrorSource(raw, body, data, execution, resultData) {
  return firstPresent(
    execution.error,
    resultData.error,
    data.error,
    raw.error,
    body.error,
    raw.cause,
    body.cause,
    {}
  );
}

function detectPattern(context) {
  const c = context.toLowerCase();
  const statusMatch = c.match(/\b(?:http\s*)?(400|401|403|404|429|500)\b/);
  const status = statusMatch ? statusMatch[1] : '';

  if (status === '429' || /rate limit|too many requests|application request limit/.test(c)) {
    return ['rate_limit', 'External API rate limit or temporary action block.', 'Wait/backoff and inspect request volume before retrying.'];
  }
  if (status === '401' || /unauthorized|invalid token|expired token|oauth|credential/.test(c)) {
    return ['credential_auth', 'Credential, token, or permission failure.', 'Verify credentials/permissions; do not patch logic first.'];
  }
  if (status === '403' || /forbidden|permission denied/.test(c)) {
    if (/robots\.txt|robots txt|blocked by robots/.test(c)) return ['robots_blocked', 'Source blocks automated fetch by robots policy.', 'Use an allowed source or upstream media URL.'];
    return ['credential_auth', 'Forbidden by API or missing permission.', 'Check token scopes, account access, and API permissions.'];
  }
  if (/robots\.txt|robots txt|blocked by robots/.test(c)) return ['robots_blocked', 'Source blocks automated fetch by robots policy.', 'Use an allowed source or upstream media URL.'];
  if (/media[_\s-]?url|fetch.*media|image url|video url|download.*image|download.*video|source_url/.test(c)) {
    return ['media_fetch_failure', 'Media URL could not be fetched or validated.', 'Inspect media URL availability, headers, and fetch node input.'];
  }
  if (/instagram|graph api|ig graph|facebook graph|media container|carousel container|ig publish/.test(c)) {
    return ['instagram_graph_api', 'Instagram Graph API rejected the request.', 'Inspect IG node parameters and Graph API response code.'];
  }
  if (/telegram|sendmessage|sendphoto|bot api/.test(c)) {
    return ['telegram_send_failure', 'Telegram API rejected the send request.', 'Inspect Telegram node payload, chat id, caption length, and media URL.'];
  }
  if (/google sheets|spreadsheet|sheet.*append|append.*sheet|sheet.*update|update.*sheet/.test(c)) {
    return ['google_sheets_write_failure', 'Google Sheets append/update failed.', 'Inspect sheet id, tab name, range, and row schema.'];
  }
  if (/missing|required|undefined|null|cannot read properties of undefined|is not defined|no item|empty input/.test(c)) {
    return ['missing_field', 'Required input field is missing or undefined.', 'Inspect previous node output and add a narrow guard/default in the failed node.'];
  }
  if (/json parse|parse json|unexpected token|invalid json|unterminated string/.test(c)) {
    return ['json_parse_error', 'Invalid JSON or malformed structured text.', 'Inspect the parser input and add strict JSON normalization at the failed node.'];
  }
  if (/encoding|utf-?8|unicode|malformed|euc-kr|base64/.test(c)) {
    return ['encoding_issue', 'Text or binary encoding mismatch.', 'Inspect encoding conversion and normalize before the failed node.'];
  }
  if (status === '400' || /bad request|invalid parameter|invalid param|unsupported post request/.test(c)) {
    return ['invalid_parameter', 'API request has invalid or incompatible parameters.', 'Inspect failed node request body and required parameter mapping.'];
  }
  if (/timeout|timed out|etimedout|esockettimedout|deadline|gateway timeout/.test(c)) {
    return ['timeout', 'External request timed out.', 'Check endpoint health and add timeout/retry policy only after confirming safety.'];
  }
  if (status === '404' || /not found/.test(c)) {
    return ['not_found', 'Referenced resource or endpoint was not found.', 'Verify resource id, URL, and upstream node mapping.'];
  }
  if (status === '500' || /internal server error/.test(c)) {
    return ['http_500', 'Upstream service returned a server error.', 'Check upstream status and retry only after confirming idempotency.'];
  }
  return ['unknown_error', 'Insufficient signal for a specific root cause.', 'Collect full failed node input/output before patching.'];
}

function severityFor(type, workflow, node, message) {
  const c = (workflow + ' ' + node + ' ' + message).toLowerCase();
  if (/publisher|publish|instagram|graph api|approval|queue/.test(c) && ['instagram_graph_api', 'credential_auth', 'missing_field', 'invalid_parameter'].includes(type)) return 'high';
  if (['credential_auth', 'google_sheets_write_failure', 'telegram_send_failure', 'media_fetch_failure'].includes(type)) return 'high';
  if (['rate_limit', 'timeout', 'http_500', 'json_parse_error', 'invalid_parameter', 'missing_field'].includes(type)) return 'medium';
  if (['not_found', 'robots_blocked'].includes(type)) return 'medium';
  return 'low';
}

function codexReady(type, workflow, node, message) {
  const hasNode = Boolean(node && node !== 'unknown');
  const hasMessage = Boolean(message && message !== 'unknown error');
  const unsafeExternal = ['credential_auth', 'rate_limit', 'robots_blocked', 'timeout', 'http_500', 'unknown_error'];
  if (!hasNode || !hasMessage || unsafeExternal.includes(type)) return false;
  return ['missing_field', 'json_parse_error', 'encoding_issue', 'invalid_parameter', 'google_sheets_write_failure', 'telegram_send_failure', 'instagram_graph_api', 'media_fetch_failure', 'not_found'].includes(type);
}

function compress(rawInput) {
  const raw = isObject(rawInput) ? rawInput : {};
  const body = isObject(raw.body) ? raw.body : raw;
  const dataValue = firstPresent(raw.data, body.data);
  const data = isObject(dataValue) ? dataValue : {};
  const executionValue = firstPresent(raw.execution, body.execution, data.execution);
  const execution = isObject(executionValue) ? executionValue : {};
  const resultDataValue = firstPresent(data.resultData, execution.resultData);
  const resultData = isObject(resultDataValue) ? resultDataValue : {};
  const errorSource = pickErrorSource(raw, body, data, execution, resultData);
  const error = isObject(errorSource) ? errorSource : {};
  const errorText = typeof errorSource === 'string' ? errorSource : '';

  const workflow = compactText(nameOf(firstPresent(
    raw.workflowName,
    body.workflowName,
    raw.workflow_name,
    body.workflow_name,
    raw.workflow,
    body.workflow,
    data.workflowName,
    data.workflow,
    execution.workflow,
    execution.workflowData
  )), 80) || 'unknown';

  const executionId = compactText(firstPresent(
    raw.execution_id,
    body.execution_id,
    raw.executionId,
    body.executionId,
    execution.id,
    data.executionId,
    data.execution_id,
    raw.id,
    body.id
  ), 80) || 'unknown';

  const failedNode = compactText(nameOf(firstPresent(
    raw.failed_node,
    body.failed_node,
    raw.failedNode,
    body.failedNode,
    raw.node,
    body.node,
    error.node,
    raw.lastNodeExecuted,
    body.lastNodeExecuted,
    execution.lastNodeExecuted,
    resultData.lastNodeExecuted,
    data.lastNodeExecuted
  )), 90) || 'unknown';

  const message = compactText(firstPresent(
    raw.error_message,
    body.error_message,
    raw.errorMessage,
    body.errorMessage,
    error.message,
    error.description,
    errorText,
    raw.message,
    body.message,
    data.message,
    resultData.message
  ), 220) || 'unknown error';

  const explicitType = compactText(firstPresent(raw.error_type, body.error_type, raw.errorType, body.errorType, error.name, error.type, error.code), 80);
  const detected = detectPattern(workflow + ' ' + failedNode + ' ' + explicitType + ' ' + message);
  const patternType = detected[0];
  const rootCause = detected[1];
  const fixDirection = detected[2];
  const errorType = explicitType || patternType;
  const severity = severityFor(patternType, workflow, failedNode, message);

  return {
    workflow,
    execution_id: executionId,
    failed_node: failedNode,
    error_type: errorType,
    error_message_short: message,
    root_cause_guess: rootCause,
    fix_direction: fixDirection,
    severity,
    codex_ready: codexReady(patternType, workflow, failedNode, message),
    compressed_at: new Date().toISOString(),
    raw_error_redacted: true
  };
}

return inputs.map((item) => ({ json: compress(item.json || {}) }));

