function asBool(value) {
  return value === true || value === 'true';
}

function compactLog(input) {
  return {
    workflow: redact(String(input.workflow || '')),
    execution_id: redact(String(input.execution_id || '')),
    failed_node: redact(String(input.failed_node || '')),
    error_type: redact(String(input.error_type || '')),
