function buildPrompt(log) {
  const ready = log.codex_ready === true;
  const decision = ready
    ? [
        'If codex_ready is true:',
        '- inspect only the named workflow and failed node',
        '- propose or apply one minimal fix',
        '- do not refactor',
        '- do not optimize',
        '- stop after one issue'
      ].join('\n')
    : [
        'If codex_ready is false:',
        '- Do not modify anything.',
        '- Explain what context is missing.',
        '- Stop.'
      ].join('\n');

  return [
    '[ROLE]',
    'You are Codex in SAFE PATCH MODE.',
    '',
    '[INPUT]',
    JSON.stringify(log, null, 2),
    '',
    '[DECISION RULE]',
    decision,
    '',
    '[CONSTRAINTS]',
    '- one issue only',
    '- one node only',
    '- no unrelated files',
    '- no credentials/webhook changes',
    '- no full-log request unless necessary',
    '',
    '[OUTPUT]',
    '[TYPE]',
    '[PLAN]',
    '[CHANGE OR PROPOSAL]',
    '[RISK]',
    '[STOP]'
  ].join('\n');
}

